/**
 * The EMS 5 schema as seen by the application: one entry per table, one type per
 * column. It mirrors db/postgres/migrations and db/d1/migrations exactly (checked
 * by tests/db/schema.test.ts) and drives typed rows, the D1 value codecs and the
 * provider-independent insert/update defaults.
 *
 *   id     uuid primary key, generated by the app when not given
 *   token  uuid generated by the app when not given (verification links)
 *   text / text?   string / nullable string (uuids, dates and enums are strings)
 *   int, num (and ?)   numbers; `gen` = generated column (read-only)
 *   bool, json     booleans / JSON values (stored as 0/1 and text on D1)
 *   ts             timestamp string, defaults to now on insert
 */

export type ColumnType = 'id' | 'token' | 'text' | 'text?' | 'int' | 'int?' | 'num' | 'num?' | 'gen' | 'bool' | 'json' | 'ts' | 'ts?';

