export const TABLES: Readonly<Record<TableName, Readonly<Record<string, ColumnType>>>> = tables;
export type TableName = keyof typeof tables;

type ValueOf<C> = C extends 'id' | 'token' | 'text' | 'ts'
  ? string
  : C extends 'text?' | 'ts?'
    ? string | null
    : C extends 'int' | 'num' | 'gen'
      ? number
      : C extends 'int?' | 'num?'
        ? number | null
        : C extends 'bool'
          ? boolean
          : unknown;

/** A full row of `T`. */
export type RowOf<T extends TableName> = { -readonly [K in keyof (typeof tables)[T]]: ValueOf<(typeof tables)[T][K]> };
/** Values accepted on insert/update: generated columns excluded, everything optional (the database enforces NOT NULL). */
export type WriteOf<T extends TableName> = Partial<Omit<RowOf<T>, GeneratedColumns<T>>>;
type GeneratedColumns<T extends TableName> = {
  [K in keyof (typeof tables)[T]]: (typeof tables)[T][K] extends 'gen' ? K : never;
}[keyof (typeof tables)[T]];

export const isTable = (name: string): name is TableName => Object.hasOwn(tables, name);

export function columnsOf(table: string): Readonly<Record<string, ColumnType>> {
  if (!isTable(table)) throw new Error(`Unknown table "${table}"`);
  return tables[table];
}

const pick = (table: string, types: readonly ColumnType[]) =>
  Object.entries(columnsOf(table)).filter(([, t]) => types.includes(t)).map(([c]) => c);

/** Columns the app fills with a new UUID on insert when missing. */
export const uuidColumns = (table: string) => pick(table, ['id', 'token']);
export const booleanColumns = (table: string) => pick(table, ['bool']);
export const jsonColumns = (table: string) => pick(table, ['json']);
export const generatedColumns = (table: string) => pick(table, ['gen']);

/* ───────────────────── relationships (embedding) ─────────────────────
 * PostgREST derives these from foreign keys; the D1 adapter uses this map to
 * emulate the same `select('*,customers(name)')` embedding. */

export interface Relation {
  table: TableName;
  /** Foreign-key column: on this table (to-one) or on the child table (to-many). */
  fk: string;
  many?: boolean;
}

const one = (table: TableName, fk: string): Relation => ({ table, fk });
const many = (table: TableName, fk: string): Relation => ({ table, fk, many: true });

export const RELATIONS: Partial<Record<TableName, Record<string, Relation>>> = {
  shops: { admins: one('admins', 'admin_id'), staff: many('staff', 'shop_id') },
  staff: { shops: one('shops', 'shop_id') },
  shop_devices: { shops: one('shops', 'shop_id'), staff: one('staff', 'staff_id') },
  licenses: { admins: one('admins', 'admin_id'), license_plans: one('license_plans', 'plan_id') },
  addon_purchases: { admins: one('admins', 'admin_id'), addons: one('addons', 'addon_key') },
  invoices: {
    shops: one('shops', 'shop_id'), customers: one('customers', 'customer_id'), suppliers: one('suppliers', 'supplier_id'),
    invoice_lines: many('invoice_lines', 'invoice_id'),
  },
  invoice_lines: { invoices: one('invoices', 'invoice_id'), products: one('products', 'product_id') },
  returns: { invoices: one('invoices', 'invoice_id'), customers: one('customers', 'customer_id'), return_items: many('return_items', 'return_id') },
  return_items: { returns: one('returns', 'return_id'), products: one('products', 'product_id'), invoice_lines: one('invoice_lines', 'invoice_line_id') },
  exchanges: { invoices: one('invoices', 'invoice_id'), customers: one('customers', 'customer_id'), exchange_items: many('exchange_items', 'exchange_id') },
  exchange_items: { exchanges: one('exchanges', 'exchange_id'), products: one('products', 'product_id'), invoice_lines: one('invoice_lines', 'invoice_line_id') },
  stock_movements: { products: one('products', 'product_id') },
  attendance: { staff: one('staff', 'staff_id') },
  salary_payments: { staff: one('staff', 'staff_id') },
  helpdesk_messages: { admins: one('admins', 'admin_id') },
  vaultium_files: { shops: one('shops', 'shop_id'), invoices: one('invoices', 'invoice_id'), expenses: one('expenses', 'expense_id') },
  zudo_conversations: { zudo_messages: many('zudo_messages', 'conversation_id') },
  sms_messages: { connect_connections: one('connect_connections', 'connection_id') },
  email_messages: { invoices: one('invoices', 'invoice_id') },
  verification_scans: { shops: one('shops', 'shop_id') },
};

export function resolveRelation(table: string, resource: string, hint?: string): Relation | null {
  const rels = isTable(table) ? RELATIONS[table] : undefined;
  if (!rels) return null;
  if (hint) return Object.values(rels).find((r) => r.fk === hint && (r.table === resource || resource === hint)) ?? null;
  return rels[resource] ?? null;
}
